# ------------------------------------------------------------------
# TRAJECTORY VISUALIZATION TOOL
#
# This module loads trajectory CSV logs generated by mapf_trajectory.py
# and visualizes robot navigation performance. The script automatically 
# loads the latest experiment logs.
#
# For each robot, the tool compares:
# - The planned waypoint sequence issued by the controller
# - The trajectory estimated by the robot itself (filtered pose)
# - Optional ArUco localization fixes
# - Optional time-coloured path progression
# ------------------------------------------------------------------

from __future__ import annotations

import argparse
import csv
import os
import re
import sys
from collections import defaultdict
from datetime import datetime
from pathlib import Path

import matplotlib.pyplot as plt
import numpy as np
from matplotlib.collections import LineCollection

# File directory setup
WS_ROOT = Path(__file__).resolve().parent.parent
DEFAULT_LOG_DIR = WS_ROOT / "logs"
DEFAULT_OUT_DIR = WS_ROOT / "analysis" / "plots"

# Arena is 3.7 m × 3.7 m
ARENA_HALF = 1.85

# EDIT HERE: list specific CSVs to plot when running with no CLI args
# If left empty, the script auto-picks the latest CSV per robot from logs/.
DEFAULT_CSVS: list[str] = [
    # ex: "logs/8_boxes_example14_robot_31c4efef_20260528_103045.csv",
]

# Optional: hardcode a specific run folder.
# Example:
DEFAULT_RUN_DIR = None
#DEFAULT_RUN_DIR = "20260521_152712_8boxes_example14"

# New format: <N_boxes>_example<M>_<robot_hostname>_<stamp>.csv
CSV_NAME_RE_NEW = re.compile(
    r"^(?P<boxes>\d+_boxes)_(?P<example>example\d+)_"
    r"(?P<robot>robot_[A-Za-z0-9]+)_(?P<stamp>\d{8}_\d{6})\.csv$"
)

# ------------------------------------------------------------------
# CSV file identification
#
# Supports both: current log naming or legacy log naming convention
#
# Extracts: robot identifier, timestamp and scenario information
# ------------------------------------------------------------------

def parse_csv_path(path: Path):
    """Return (robot, stamp, scenario) — scenario is None for old-format files."""
    m = CSV_NAME_RE_NEW.match(path.name)
    if m:
        scenario = f"{m.group('boxes')} {m.group('example')}"
        return m.group("robot"), m.group("stamp"), scenario
    return None, None, None

# ------------------------------------------------------------------
# CSV data loading
#
# Reads trajectory logs exported by mapf_trajectory.py and converts
# columns into NumPy arrays.
# ------------------------------------------------------------------

def load_csv(path: Path) -> dict[str, np.ndarray]:
    rows = []
    with path.open() as f:
        reader = csv.DictReader(f)
        for row in reader:
            rows.append(row)
    if not rows:
        raise ValueError(f"{path} is empty")
    cols = {k: np.array([r[k] for r in rows]) for k in rows[0].keys()}
    floats = {
        "time", "target_x", "target_y",
        "filtered_x", "filtered_y", "filtered_yaw",
        "raw_odom_x", "raw_odom_y", "raw_odom_yaw",
        "aruco_x", "aruco_y", "aruco_yaw", "aruco_age",
        "cmd_vx", "cmd_vy", "dist_to_target", "min_dist",
    }
    ints = {"lap_count", "goal_index", "wp_index", "aruco_count",
            "lifter_up", "lifter_toggle_count"}
    for k in list(cols):
        if k in floats:
            cols[k] = cols[k].astype(float)
        elif k in ints:
            cols[k] = cols[k].astype(int)
    return cols

# ------------------------------------------------------------------
# Planned Waypoint Reconstruction
#
# The controller stores only the currently active waypoint in each
# control cycle.
# ------------------------------------------------------------------

def planned_path(cols) -> np.ndarray:
    xs, ys = cols["target_x"], cols["target_y"]
    pts = [(xs[0], ys[0])]
    for x, y in zip(xs[1:], ys[1:]):
        if (x, y) != pts[-1]:
            pts.append((x, y))
    return np.asarray(pts)

# ------------------------------------------------------------------
# ArUco file extraction
#
# Extracts one representative position for each newly received
# ArUco localization update. The resulting points can be overlaid on trajectory plots for
# localization analysis.
# ------------------------------------------------------------------

def aruco_fix_points(cols) -> np.ndarray:
    counts = cols["aruco_count"]
    if len(counts) == 0:
        return np.empty((0, 2))
    keep = np.empty(len(counts), dtype=bool)
    keep[0] = True
    keep[1:] = counts[1:] != counts[:-1]
    keep &= counts > 0
    return np.column_stack([cols["aruco_x"][keep], cols["aruco_y"][keep]])

# ------------------------------------------------------------------
# EKF settling phase removal
#
# Robots remain stationary during pre-arm initialization, ArUco 
# acquisition and EKF convergence. This removes initialization 
# noise from trajectory visualizations.
# ------------------------------------------------------------------

def trim_to_settled(cols) -> dict:
    moved = (np.abs(cols["cmd_vx"]) > 1e-6) | (np.abs(cols["cmd_vy"]) > 1e-6)
    if not moved.any():
        return cols  # robot never moved — leave data untouched
    start = int(np.argmax(moved))
    return {k: v[start:] for k, v in cols.items()}

# ------------------------------------------------------------------
# Single robot trajectory visualization
#
# Draws all information related to a single robot:
#
# Plots: planned waypoint sequence, estimated trajectory, start 
# and end markers, optional ArUco observations and optional 
# time-based colouring.
# ------------------------------------------------------------------

def draw_robot_axes(ax, cols, *, show_aruco, color_by_time, title):
    ax.set_aspect("equal")
    # Arena spans [-1.85, 1.85] in both x and y
    ax.set_xlim(-ARENA_HALF, ARENA_HALF)
    ax.set_ylim(ARENA_HALF, -ARENA_HALF)

    ticks = np.linspace(-ARENA_HALF, ARENA_HALF, 7)

    ax.set_xticks(ticks)
    ax.set_yticks(ticks)

    ax.grid(True, alpha=0.3)

    ax.set_xlabel("y [m]")
    ax.set_ylabel("x [m]")
    ax.set_title(title, fontsize=10)

    # Planned waypoint path (dashed, with goal markers + numbers)
    plan = planned_path(cols)
    ax.plot(plan[:, 1], plan[:, 0], linestyle="--", color="0.4", linewidth=1.2, label="planned (waypoints)", zorder=2)
    ax.scatter(plan[:, 1], plan[:, 0], color="0.3", marker="s", s=18, zorder=3)

    for i, (x, y) in enumerate(plan):
        ax.annotate(str(i), (y, x),
                    textcoords="offset points",
                    xytext=(4, 4),
                    fontsize=7,
                    color="0.3")

    fx, fy = cols["filtered_y"], cols["filtered_x"]
    t = cols["time"]
    if color_by_time and len(fx) > 1:
        pts = np.column_stack([fx, fy]).reshape(-1, 1, 2)
        segs = np.concatenate([pts[:-1], pts[1:]], axis=1)
        lc = LineCollection(segs, cmap="viridis",
                            norm=plt.Normalize(t.min(), t.max()),
                            linewidth=1.6, zorder=4)
        lc.set_array(t[:-1])
        line = ax.add_collection(lc)
        cb = plt.colorbar(line, ax=ax, shrink=0.7, pad=0.02)
        cb.set_label("time since start [s]", fontsize=8)
        cb.ax.tick_params(labelsize=7)
        # legend proxy
        ax.plot([], [], color="tab:blue", label="believed path (time-coloured)")
    else:
        ax.plot(fx, fy, color="tab:blue", linewidth=1.4,
                label="believed path (filtered)", zorder=4)

    # Optional ArUco fixes
    if show_aruco:
        ar = aruco_fix_points(cols)
        if len(ar):
            #ax.scatter(ar[:, 0], ar[:, 1], s=6, color="tab:red", alpha=0.4, label=f"ArUco fixes (n={len(ar)})", zorder=5)
            ax.scatter(ar[:, 1], ar[:, 0], s=6, color="tab:red", alpha=0.4, label=f"ArUco fixes (n={len(ar)})", zorder=5)

    # Start / end markers on believed path
    if len(fx):
        ax.scatter([fx[0]], [fy[0]], color="green", marker="o", s=50,
                   edgecolor="black", linewidths=0.8, zorder=6, label="start")
        ax.scatter([fx[-1]], [fy[-1]], color="red", marker="X", s=60,
                   edgecolor="black", linewidths=0.8, zorder=6, label="end")

    ax.legend(loc="best", fontsize=7, framealpha=0.85)

# ------------------------------------------------------------------
# Input discovery
#
# Resolves which trajectory logs should be visualized.
# ------------------------------------------------------------------

def gather_inputs(csv_args: list[str]) -> list[Path]:
    # Explicit CSVs from CLI
    if csv_args:
        paths = [Path(p) for p in csv_args]
        for p in paths:
            if not p.exists():
                sys.exit(f"CSV not found: {p}")
        return sorted(paths)

    # Hardcoded CSV list
    if DEFAULT_CSVS:
        paths = []
        for s in DEFAULT_CSVS:
            p = Path(s)
            if not p.is_absolute():
                p = WS_ROOT / p
            if not p.exists():
                sys.exit(f"CSV not found: {p}")
            paths.append(p)
        return sorted(paths)

    # Hardcoded run directory
    if DEFAULT_RUN_DIR is not None:
        run_dir = DEFAULT_LOG_DIR / DEFAULT_RUN_DIR
    else:
        # Auto-pick latest run directory
        run_dirs = [p for p in DEFAULT_LOG_DIR.iterdir() if p.is_dir()]

        if not run_dirs:
            sys.exit(f"No run directories found in {DEFAULT_LOG_DIR}")

        run_dir = max(run_dirs, key=lambda p: p.name)

    print(f"Using run directory: {run_dir}")

    csvs = sorted(run_dir.glob("*.csv"))

    if not csvs:
        sys.exit(f"No CSVs found in {run_dir}")

    return csvs

# ------------------------------------------------------------------
# Multi-robot figure generation
#
# Creates a complete visualization containing one subplot per robot.
# The resulting figure summarizes an entire experiment run.
# ------------------------------------------------------------------

def make_figure(csvs: list[Path], *, show_aruco, color_by_time,
                trim_settle=True, run_label=""):
    per_robot = {}
    scenarios = set()
    for p in csvs:
        robot, stamp, scenario = parse_csv_path(p)
        if scenario:
            scenarios.add(scenario)
        label_parts = []
        if robot:
            label_parts.append(robot)
        if stamp:
            label_parts.append(stamp)
        label = "\n".join(label_parts) if label_parts else p.name
        cols = load_csv(p)
        if trim_settle:
            cols = trim_to_settled(cols)
        per_robot[label] = cols

    n = len(per_robot)
    cols_per_row = min(n, 3)
    rows = (n + cols_per_row - 1) // cols_per_row
    fig, axes = plt.subplots(rows, cols_per_row,
                             figsize=(6 * cols_per_row, 6 * rows),
                             squeeze=False)

    flat = [ax for row in axes for ax in row]
    for ax, (label, cols) in zip(flat, per_robot.items()):
        draw_robot_axes(ax, cols,
                        show_aruco=show_aruco,
                        color_by_time=color_by_time,
                        title=label)
    for ax in flat[len(per_robot):]:
        ax.axis("off")

    overlay_bits = []
    if show_aruco:
        overlay_bits.append("+ArUco")
    if color_by_time:
        overlay_bits.append("time-coloured")
    if trim_settle:
        overlay_bits.append("start = settle-complete")
    suptitle = "Believed path vs planned waypoints"
    if scenarios:
        suptitle += f"  ({', '.join(sorted(scenarios))})"
    if run_label:
        suptitle += f"  ({run_label})"
    if overlay_bits:
        suptitle += "  [" + " ".join(overlay_bits) + "]"
    fig.suptitle(suptitle, fontsize=11)
    fig.tight_layout(rect=[0.04, 0.03, 1, 0.97])
    return fig

# ------------------------------------------------------------------
# Program entry point
#
# Generated figures are saved as PNG files.
# ------------------------------------------------------------------

def main():
    ap = argparse.ArgumentParser(description=__doc__.split("\n", 1)[0])
    ap.add_argument("csv", nargs="*",
                    help="CSV files to plot. Default: DEFAULT_CSVS at top of "
                         "this file, else latest per robot in logs/.")
    ap.add_argument("--aruco", action="store_true",
                    help="Overlay ArUco fix scatter")
    ap.add_argument("--time-color", action="store_true",
                    help="Colour the believed path by elapsed time")
    ap.add_argument("--all-variants", action="store_true",
                    help="Produce one PNG per overlay combination")
    ap.add_argument("--no-trim", action="store_true",
                    help="Include pre-settle rows (default: start at first "
                         "non-zero command velocity)")
    ap.add_argument("--out-dir", type=Path, default=None,
                    help=f"Output directory (default: {DEFAULT_OUT_DIR}/<stamp>)")
    ap.add_argument("--show", action="store_true",
                    help="Open the plot window after saving")
    ap.add_argument("--label", default="",
                    help="Free-text run label shown in suptitle (e.g. odometry source)")
    args = ap.parse_args()

    csvs = gather_inputs(args.csv)
    print(f"Plotting {len(csvs)} CSV(s):")
    for p in csvs:
        print(f"  {p}")

    stamp = datetime.now().strftime("%Y%m%d_%H%M%S")
    out_dir = args.out_dir or (DEFAULT_OUT_DIR / stamp)
    out_dir.mkdir(parents=True, exist_ok=True)

    if args.all_variants:
        variants = [
            ("baseline",      dict(show_aruco=False, color_by_time=False)),
            ("aruco",         dict(show_aruco=True,  color_by_time=False)),
            ("time_coloured", dict(show_aruco=False, color_by_time=True)),
            ("all_overlays",  dict(show_aruco=True,  color_by_time=True)),
        ]
    else:
        variants = [("custom", dict(show_aruco=args.aruco,
                                    color_by_time=args.time_color))]

    trim_settle = not args.no_trim
    saved = []
    for name, kwargs in variants:
        fig = make_figure(csvs, run_label=args.label,
                          trim_settle=trim_settle, **kwargs)
        out = out_dir / f"trajectory_{name}.png"
        fig.savefig(out, dpi=150)
        saved.append(out)
        print(f"  wrote {out}")
        if not args.show:
            plt.close(fig)

    if args.show:
        plt.show()

    print(f"\nDone. {len(saved)} PNG(s) in {out_dir}")


if __name__ == "__main__":
    main()